  ('30000000-0000-4000-8000-000000000001', 'ethiopian-new-year-celebration-dc-2026', 'Ethiopian New Year Celebration in DC', 'A large Enkutatash celebration with music, food, fashion, comedy, and community awards.', 'Eatopia Eatery brings Ethiopian music, food, fashion, comedy, cultural performances, vendors, and a midnight New Year countdown to the convention center.', '00000000-0000-4000-8000-000000000102', '20000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000206', '10000000-0000-4000-8000-000000000001', '2026-09-11T22:30:00Z', '2026-09-12T05:00:00Z', 'https://www.eventbrite.com/e/ethiopian-new-years-celebration-in-dc-tickets-1998693574284', 'See ticket page', true, false, 'approved', 'https://www.eventbrite.com/e/ethiopian-new-years-celebration-in-dc-tickets-1998693574284', '2026-08-27T16:00:00Z', now()),
  ('30000000-0000-4000-8000-000000000002', 'living-archive-eritrean-ethiopian-stories', 'The Living Archive: Eritrean and Ethiopian Stories', 'Artists and writers discuss how diaspora stories are preserved through art and fiction.', 'A DC Public Library panel brings together literary and artistic perspectives from storytellers in the Eritrean and Ethiopian diasporas.', '00000000-0000-4000-8000-000000000102', '20000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000203', '10000000-0000-4000-8000-000000000002', '2026-09-22T23:00:00Z', '2026-09-23T00:15:00Z', 'https://dclibrary.libnet.info/event/17273160', 'Free registration', true, false, 'approved', 'https://dclibrary.libnet.info/event/17273160', '2026-08-27T16:00:00Z', now()),
  ('30000000-0000-4000-8000-000000000003', 'medhane-alem-labor-day-festival-2026', 'Medhane Alem Labor Day Weekend Festival', 'Two days of Eritrean food, coffee, music, family activities, and fellowship.', 'The annual community festival includes Eritrean food, a traditional coffee ceremony, mezmur and dance, childrens activities, tours, vendors, and raffles.', '00000000-0000-4000-8000-000000000102', '20000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000206', '10000000-0000-4000-8000-000000000003', '2026-09-05T15:00:00Z', '2026-09-06T22:00:00Z', 'https://www.medhanealemorthodox.org/events/labor-day-weekend-festival-2026', 'Free', false, false, 'approved', 'https://www.medhanealemorthodox.org/events/labor-day-weekend-festival-2026', '2026-08-27T16:00:00Z', now()),
  ('30000000-0000-4000-8000-000000000004', 'dc-ethiopian-eritrean-new-year-party-2026', 'DC Ethiopian and Eritrean New Year Celebration', 'A diaspora New Year party in Ivy City presented by Diaspora Handbook.', 'Diaspora Handbook presents a Friday night Ethiopian and Eritrean New Year celebration in Washington, DC.', '00000000-0000-4000-8000-000000000102', '20000000-0000-4000-8000-000000000004', '00000000-0000-4000-8000-000000000201', '10000000-0000-4000-8000-000000000004', '2026-09-12T02:00:00Z', '2026-09-12T07:00:00Z', 'https://posh.vip/e/dcs-biggest-ethiopian-eritrean-new-years-party', 'See ticket page', true, false, 'approved', 'https://posh.vip/e/dcs-biggest-ethiopian-eritrean-new-years-party', '2026-08-27T16:00:00Z', now()),
